function validate([head]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 10000) return 'The list holds 1 to 10000 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < 0 || v > 9)) return 'Each node holds one digit from 0 to 9.';
  if (head.length > 1 && head[0] === 0) return 'The number cannot start with a zero unless it is 0 itself.';
  return null;
}

