function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 7);
  // Sometimes lean on high digits so carries are frequent, sometimes on low ones so they are rare.
  const mode = Math.floor(rand() * 3);
  const digit = () => (mode === 0 ? Math.floor(rand() * 10) : mode === 1 ? 5 + Math.floor(rand() * 5) : Math.floor(rand() * 5));
  const digits = Array.from({ length: n }, digit);
  if (n > 1 && digits[0] === 0) digits[0] = 1 + Math.floor(rand() * 9);
  return [digits];
}
